//! Row change types for Raft replication
//!
//! These types represent the row-level changes generated by SQL DML operations
//! that need to be replicated through Raft consensus.

use serde::{Deserialize, Serialize};

/// The type of change operation
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum ChangeOp {
    /// Insert a new row
    Insert,
    /// Update an existing row
    Update,
    /// Delete a row
    Delete,
}

/// A single row change to be replicated
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RowChange {
    /// Encoded row key
    pub key: Vec<u8>,
    /// Encoded row value (None for DELETE)
    pub value: Option<Vec<u8>>,
    /// Type of change
    pub op: ChangeOp,
    /// Expected version (txn_id) for OCC conflict detection
    ///
    /// For UPDATE/DELETE: The txn_id of the row version we read.
    /// In apply(), if the current row has a different txn_id, the write is rejected
    /// as a concurrent modification conflict.
    #[serde(default)]
    pub expected_version: Option<u64>,
    /// For a row inserted into a table with an AUTO_INCREMENT column: the
    /// table's counter after this row. Applying the row raises the stored
    /// counter to it.
    #[serde(default)]
    pub auto_inc: Option<u64>,
}

impl RowChange {
    /// The table the row belongs to: the ID its key begins with. `None`
    /// for a key that is not a table's (there are none in what the server
    /// writes; tests of the log write such keys).
    pub fn table(&self) -> Option<crate::executor::encoding::TableId> {
        crate::executor::encoding::table_of_row_key(&self.key)
    }

    /// Create an INSERT change
    pub fn insert(key: Vec<u8>, value: Vec<u8>) -> Self {
        Self {
            key,
            value: Some(value),
            op: ChangeOp::Insert,
            expected_version: None,
            auto_inc: None,
        }
    }

    /// Record the table's AUTO_INCREMENT counter after this row.
    pub fn with_auto_inc(mut self, next: Option<u64>) -> Self {
        self.auto_inc = next;
        self
    }

    /// Create an UPDATE change
    pub fn update(key: Vec<u8>, value: Vec<u8>) -> Self {
        Self {
            key,
            value: Some(value),
            op: ChangeOp::Update,
            expected_version: None,
            auto_inc: None,
        }
    }

    /// Create an UPDATE change with OCC version check
    ///
    /// The expected_version is the txn_id of the row version we read.
    /// apply() will reject the update if the row has been modified since.
    pub fn update_with_version(key: Vec<u8>, value: Vec<u8>, expected_version: u64) -> Self {
        Self {
            key,
            value: Some(value),
            op: ChangeOp::Update,
            expected_version: Some(expected_version),
            auto_inc: None,
        }
    }

    /// Create a DELETE change
    pub fn delete(key: Vec<u8>) -> Self {
        Self {
            key,
            value: None,
            op: ChangeOp::Delete,
            expected_version: None,
            auto_inc: None,
        }
    }

    /// Create a DELETE change with OCC version check
    pub fn delete_with_version(key: Vec<u8>, expected_version: u64) -> Self {
        Self {
            key,
            value: None,
            op: ChangeOp::Delete,
            expected_version: Some(expected_version),
            auto_inc: None,
        }
    }

    /// Create a DELETE change with value included for tracking
    ///
    /// Used for system table deletes where the row data is needed to identify
    /// what table/index is being dropped (for catalog rebuild in apply()).
    pub fn delete_with_value(key: Vec<u8>, value: Vec<u8>) -> Self {
        Self {
            key,
            value: Some(value),
            op: ChangeOp::Delete,
            expected_version: None,
            auto_inc: None,
        }
    }
}

/// A set of row changes from a single transaction
///
/// When the executor completes a DML operation, it produces a ChangeSet
/// that is then proposed to Raft for consensus and replication.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct ChangeSet {
    /// Transaction ID that produced these changes
    pub txn_id: u64,
    /// The row-level changes
    pub changes: Vec<RowChange>,
    /// When true, duplicate-key errors are suppressed (INSERT IGNORE semantics).
    /// Rows that conflict with existing keys are silently skipped.
    #[serde(default)]
    pub ignore_duplicates: bool,
}

impl ChangeSet {
    /// Create a new empty change set
    pub fn new(txn_id: u64) -> Self {
        Self {
            txn_id,
            changes: Vec::new(),
            ignore_duplicates: false,
        }
    }

    /// Create a change set with pre-populated changes
    pub fn new_with_changes(txn_id: u64, changes: Vec<RowChange>) -> Self {
        Self {
            txn_id,
            changes,
            ignore_duplicates: false,
        }
    }

    /// Create a change set with pre-populated changes and IGNORE semantics
    pub fn new_with_changes_ignore(
        txn_id: u64,
        changes: Vec<RowChange>,
        ignore_duplicates: bool,
    ) -> Self {
        Self {
            txn_id,
            changes,
            ignore_duplicates,
        }
    }

    /// Add a change to the set
    pub fn push(&mut self, change: RowChange) {
        self.changes.push(change);
    }

    /// Check if the change set is empty
    pub fn is_empty(&self) -> bool {
        self.changes.is_empty()
    }

    /// Get the number of changes
    pub fn len(&self) -> usize {
        self.changes.len()
    }

    /// Take ownership of the changes
    pub fn into_changes(self) -> Vec<RowChange> {
        self.changes
    }

    /// Iterate over the changes
    pub fn iter(&self) -> impl Iterator<Item = &RowChange> {
        self.changes.iter()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_row_change_insert() {
        let change = RowChange::insert(vec![1, 2, 3], vec![4, 5, 6]);
        assert_eq!(change.op, ChangeOp::Insert);
        assert!(change.value.is_some());
    }

    #[test]
    fn test_row_change_delete() {
        let change = RowChange::delete(vec![1, 2, 3]);
        assert_eq!(change.op, ChangeOp::Delete);
        assert!(change.value.is_none());
    }

    #[test]
    fn a_change_belongs_to_the_table_its_key_begins_with() {
        use crate::executor::encoding::{encode_row_key, TableId};
        let change = RowChange::insert(encode_row_key(TableId(1234), 7), vec![2]);
        assert_eq!(change.table(), Some(TableId(1234)));
        assert_eq!(RowChange::insert(vec![1], vec![2]).table(), None);
    }

    #[test]
    fn test_change_set() {
        let mut cs = ChangeSet::new(42);
        assert!(cs.is_empty());

        cs.push(RowChange::insert(vec![1], vec![2]));
        cs.push(RowChange::delete(vec![3]));

        assert_eq!(cs.len(), 2);
        assert_eq!(cs.txn_id, 42);
    }

    #[test]
    fn test_serialization() {
        let change = RowChange::insert(vec![1, 2], vec![3, 4]);
        let serialized = bincode::serialize(&change).unwrap();
        let deserialized: RowChange = bincode::deserialize(&serialized).unwrap();

        assert_eq!(change.key, deserialized.key);
        assert_eq!(change.value, deserialized.value);
        assert_eq!(change.op, deserialized.op);
    }

    #[test]
    fn test_changeset_serialization() {
        let mut cs = ChangeSet::new(123);
        cs.push(RowChange::insert(vec![1], vec![2]));
        cs.push(RowChange::update(vec![3], vec![4]));

        let serialized = bincode::serialize(&cs).unwrap();
        let deserialized: ChangeSet = bincode::deserialize(&serialized).unwrap();

        assert_eq!(cs.txn_id, deserialized.txn_id);
        assert_eq!(cs.len(), deserialized.len());
    }
}
